function parseDuration(s) {
    /**
     * Parse a duration string like '1d2h30m', '45s', '2h5s' and return the total number of seconds.
     *
     * Supported units:
     *     d - days
     *     h - hours
     *     m - minutes
     *     s - seconds
     *
     * Examples:
     *     parseDuration('1d2h') -> 93600
     *     parseDuration('1h30m') -> 5400
     *     parseDuration('45s') -> 45
     *     parseDuration('2h5s') -> 7205
     */
    const totalSeconds = 0;

    // Match days, hours, minutes, and seconds
    const daysMatch = s.match(/(\d+)d/);
    const hoursMatch = s.match(/(\d+)h/);
    const minutesMatch = s.match(/(\d+)m/);
    const secondsMatch = s.match(/(\d+)s/);

    if (daysMatch) {
        totalSeconds += parseInt(daysMatch[1], 10) * 86400;
    }
    if (hoursMatch) {
        totalSeconds += parseInt(hoursMatch[1], 10) * 3600;
    }
    if (minutesMatch) {
        totalSeconds += parseInt(minutesMatch[1], 10) * 60;
    }
    if (secondsMatch) {
        totalSeconds += parseInt(secondsMatch[1], 10);
    }

    return totalSeconds;
}
